MATCH (source:PlantItem {tag: 'C-20-1'}), (target:PlantItem {tag: 'C-43-3'})
OPTIONAL MATCH path = (source)-[:send_to*]->(target)
RETURN source.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS can_reach }

MATCH (source:PlantItem {tag: "E-7-4"})
RETURN source.tag AS source_tag,
       "V-41-4" AS target_tag,
       EXISTS {
         MATCH (source)-[:send_to*1..]->(:PlantItem {tag: "V-41-4"})
       } AS reachable Be safe query allows internal node regardless PlantItem target yes.

MATCH (start:PlantItem {tag: 'TK-8-3'}), (target:PlantItem {tag: 'V-24-2'})
RETURN start.tag AS from_tag, target.tag AS to_tag,
       EXISTS { MATCH (start)-[:send_to*]->(target) } AS can_reach;

MATCH path = (start:PlantItem {tag: "TK-3-3"})-[:send_to*1..]->(end:PlantItem {tag: "T-47-4"})
RETURN [item IN nodes(path) | item.tag] AS tags
LIMIT 1;

MATCH (c:Compressor)
WHERE toString(c.unit_id) = '15'
RETURN count(DISTINCT c.tag) AS compressor_count;

MATCH (hx:HeatExchanger)
WHERE hx.unit_id = '16'
RETURN count(DISTINCT hx.tag) AS heat_exchanger_count;

MATCH (start:PlantItem {tag: 'LV-3-1'}), (finish:PlantItem {tag: 'P-45-4'})
MATCH p = shortestPath((start)-[:send_to*]->(finish))
RETURN [n IN nodes(p) WHERE n:Equipment OR n:OperatedValve OR n:BallValve OR n:CheckValve OR n:GlobeValve | n.tag] AS flow_path_tags;

MATCH (equipment:PlantItem {tag: 'E-30-3'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: "P-9-1"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment {tag: 'C-26-1'})-[:send_to]-(valve:OperatedValve)<-[:control]-(:ActuatingFunction)<-[:send_signal_to]-(loop:ProcessInstrumentationFunction)
RETURN DISTINCT loop.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (s:PlantItem {tag: 'C-30-1'}), (t:PlantItem {tag: 'P-24-3'})
MATCH p = shortestPath((s)-[:send_to*]->(t))
RETURN [n IN nodes(p) WHERE n:Equipment OR n:BallValve OR n:CheckValve OR n:GlobeValve OR n:OperatedValve | n.tag] AS flow_path;

MATCH (item:PlantItem {tag: "C-26-2"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "V-18-4"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "TK-23-4"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'V-46-1'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'C-2-3'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
THOOK

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-24-5"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;
